function output=run_repair_response_calibration(outputDir)
% Characterize raw deletion versus exact post-repair delivery response.
narginchk(1,1);here=fileparts(mfilename('fullpath'));root=fileparts(fileparts(here));add_paths(root,here);create_empty(outputDir);
artifactFile=fullfile(root,'results','task25_27_pipeline_20deg.mat');stage1File=fullfile(root,'results','full_integrated_layer_20deg_job22180','alpha_0p3','alpha_0p3_final.mat');anchorFile=fullfile(root,'results','survivor_compression_boundary_job22813','survivor_compression_boundary_complete.mat');legacyDir=fullfile(root,'results','bdt_aware_active_gate_job23262');priorDir=fullfile(root,'results','adaptive_survivor_boundary_job22926');
source=load(artifactFile,'cfg','machine','dij','stf','pln','map');stage1=load(stage1File,'final','supportMask');a=load(anchorFile,'output');a=a.output;patient=load(source.cfg.patientFile,'ct','cst');cfg=merge_structs(default_config(),source.cfg);allowedFull=reshape(logical(stage1.supportMask),[],1);[dij,toFull,~,map]=reduce_dij_to_support(source.dij,allowedFull,source.map);for i=1:numel(map),map(i).originalGlobalIx=map(i).globalIx;map(i).globalIx=i;end;[groups,~]=build_group_index(map);[groupsFull,~]=build_group_index(source.map);D=nominal(dij);model=build_matrad_dose_model(dij,patient.cst,source.pln,0);wRef=reshape(double(stage1.final.w(toFull)),[],1);reference=evaluate_plan(wRef,model,D,patient,cfg,source,groups,groupsFull,toFull,stage1.final.w);w=reshape(double(a.w),[],1);anchor=evaluate_plan(w,model,D,patient,cfg,source,groups,groupsFull,toFull,stage1.final.w);assert(anchor.activeSpots==133790&&clinical_state(anchor,reference).feasible);
settings=struct('cardinality',445,'zeroTolerance',1e-10,'candidateCount',24,'maxOuter',4,'activeMaxIter',80,'activeMaxCPU',120000);spec=build_clinical_gate_spec(D,patient.cst,reference.dose,2,.2);[anchorGate,gateJ]=evaluate_clinical_gates(D,w,spec,true);[~,grad]=evaluate_matrad_dose_model(model,w,true);geom=geometry_arrays(map,source.stf);spotCost=spot_cost(w,grad,gateJ,spec,anchor.objective);layerT=readtable(fullfile(legacyDir,'layer_screening.csv'));prior1=load(fullfile(priorDir,'attempt_01.mat'),'death');prior2=load(fullfile(priorDir,'attempt_02.mat'),'death');master=unique([prior1.death(:);prior2.death(:)],'stable');
rows=repmat(empty_response(),0,1);gateRows=repmat(empty_gate_row(),0,1);componentRows=repmat(empty_component_row(),0,1);supportRows=repmat(empty_support_row(),0,1);allBlocks=repmat(block_template(),0,1);total=tic;
% Existing job-23262 responses are reused exactly; no repeated optimization.
for k=1:4
 d=load(fullfile(legacyDir,sprintf('proposal_%02d.mat',k)),'pr','wr','cg');b=block_template();b.name=['legacy_' d.pr.name];b.phase='LEGACY_CALIBRATION';b.method=d.pr.kind;b.death=reshape(double(d.pr.death),[],1);b.rawGain=double(d.pr.predictedBDTReduction);b.predictedRepairCost=double(d.pr.predictedRepairCost);allBlocks(end+1)=b;[r,gc,dc,sr]=analyze_block(numel(allBlocks),b,w,d.wr,anchor,reference,model,D,patient,cfg,source,groups,groupsFull,toFull,stage1.final.w,spec,anchorGate,geom,d.cg,toc(total));rows(end+1)=r;gateRows=[gateRows;gc];componentRows=[componentRows;dc];supportRows(end+1)=sr;
end
calibCP=~ismember(geom.cp,unique(geom.cp(mod(geom.cp,3)==0)));holdCP=mod(geom.cp,3)==0;
calPool=generate_candidate_pool('calibration_oracle',settings.candidateCount,settings.cardinality,calibCP,w,groups,layerT,spotCost,cfg,source,groupsFull,toFull,stage1.final.w);writetable(pool_table(calPool),fullfile(outputDir,'calibration_oracle_pool.csv'));ord=oracle_order(calPool);chosen=ord(1:min(2,numel(ord)));
for q=1:numel(chosen)
 b=calPool(chosen(q));b.name=sprintf('calibration_oracle_%d',q);b.phase='NEW_CALIBRATION';b.method='EXACT_DELIVERY_ORACLE_SUBSET';[wa,cg]=repair_block(b,w,dij,patient,source,reference,settings);allBlocks(end+1)=b;[r,gc,dc,sr]=analyze_block(numel(allBlocks),b,w,wa,anchor,reference,model,D,patient,cfg,source,groups,groupsFull,toFull,stage1.final.w,spec,anchorGate,geom,cg,toc(total));rows(end+1)=r;gateRows=[gateRows;gc];componentRows=[componentRows;dc];supportRows(end+1)=sr;checkpoint(outputDir,numel(allBlocks),b,wa,cg,r,gc,dc,sr);flush(outputDir,rows,gateRows,componentRows,supportRows);clear wa cg;
end
cal=derive_mechanistic_calibration(rows,settings.cardinality);save(fullfile(outputDir,'mechanistic_calibration.mat'),'cal');writetable(struct2table(cal),fullfile(outputDir,'mechanistic_calibration.csv'));
% Prospective held-out blocks use CPs excluded from new calibration candidates.
heldPool=generate_candidate_pool('heldout',settings.candidateCount,settings.cardinality,holdCP,w,groups,layerT,spotCost,cfg,source,groupsFull,toFull,stage1.final.w);for i=1:numel(heldPool),heldPool(i).predictedRealDelta=repair_aware_prediction(heldPool(i),cal,source.machine);end;writetable(pool_table(heldPool),fullfile(outputDir,'heldout_candidate_pool.csv'));
cardDeath=cardinality_block(master,holdCP,spotCost,settings.cardinality);card=describe_block('heldout_cardinality','HELDOUT_PROSPECTIVE','CARDINALITY_ONLY',cardDeath,w,groups,spotCost,cfg,source,groupsFull,toFull,stage1.final.w);[~,oldIx]=max([heldPool.currentScore]);old=heldPool(oldIx);old.name='heldout_current_bdt';old.phase='HELDOUT_PROSPECTIVE';old.method='CURRENT_BDT_AWARE';eligible=1:numel(heldPool);eligible(ismember(eligible,oldIx))=[];[~,j]=min([heldPool(eligible).predictedRealDelta]);nw=heldPool(eligible(j));nw.name='heldout_repair_aware';nw.phase='HELDOUT_PROSPECTIVE';nw.method='REPAIR_AWARE_DELIVERY';testBlocks=[card old nw];
for q=1:numel(testBlocks)
 b=testBlocks(q);b.predictedRealDelta=repair_aware_prediction(b,cal,source.machine);[wa,cg]=repair_block(b,w,dij,patient,source,reference,settings);allBlocks(end+1)=b;[r,gc,dc,sr]=analyze_block(numel(allBlocks),b,w,wa,anchor,reference,model,D,patient,cfg,source,groups,groupsFull,toFull,stage1.final.w,spec,anchorGate,geom,cg,toc(total));rows(end+1)=r;gateRows=[gateRows;gc];componentRows=[componentRows;dc];supportRows(end+1)=sr;checkpoint(outputDir,numel(allBlocks),b,wa,cg,r,gc,dc,sr);flush(outputDir,rows,gateRows,componentRows,supportRows);clear wa cg;
end
held=rows(strcmp({rows.phase},'HELDOUT_PROSPECTIVE'));summary=summarize(rows,held,cal);output=struct('classification',summary.classification,'anchor',anchor,'rows',rows,'gateRows',gateRows,'componentRows',componentRows,'supportRows',supportRows,'calibration',cal,'heldout',held,'summary',summary,'blocks',{allBlocks},'wallSeconds',toc(total));save(fullfile(outputDir,'repair_response_calibration_complete.mat'),'output','-v7.3');flush(outputDir,rows,gateRows,componentRows,supportRows);write_report(outputDir,output);fprintf('FINAL_STATUS %s heldout_old_mae=%.4f heldout_new_mae=%.4f\n',summary.classification,summary.oldPredictionMAE,summary.newPredictionMAE);
end

function [wa,cg]=repair_block(b,w,dij,patient,source,reference,s)
support=w>s.zeroTolerance;support(b.death)=false;[dijR,r2f]=reduce_dij_to_support(dij,support);m=build_matrad_dose_model(dijR,patient.cst,source.pln,0);Dr=nominal(dijR);set=struct('maxOuter',s.maxOuter,'maxIter',s.activeMaxIter,'maxCPU',s.activeMaxCPU);cg=run_constraint_generation_repair(m,w(r2f),Dr,patient.cst,reference.dose,set);wa=zeros(size(w));wa(r2f)=cg.w;
end

function pool=generate_candidate_pool(prefix,n,card,eligible,w,groups,T,cost,cfg,source,groupsFull,toFull,template)
gid=(1:numel(groups))';cp=arrayfun(@(x)x.cpIndex,groups)';valid=false(numel(groups),1);for k=1:numel(groups),ix=groups(k).ix;valid(k)=any(eligible(ix)&w(ix)>1e-10);end;base=double(T.predT)./max(double(T.approx),1e-10);base(~isfinite(base))=0;pool=repmat(block_template(),n,1);
for seed=1:n
 utility=log(max(base,1e-12))+0.22*sin(gid*(seed+2)*0.731)-0.03*mod(cp+seed,5);utility(~valid)=-Inf;[~,order]=sort(utility,'descend');E=[];
 for k=reshape(order,1,[]),ix=groups(k).ix;ix=ix(eligible(ix)&w(ix)>1e-10);if isempty(ix),continue;end;remain=card-numel(E);if remain<=0,break;end;if numel(ix)<=remain,E=[E;ix];else,[~,o]=sort(cost(ix),'ascend');E=[E;ix(o(1:remain))];end;if numel(E)>=card,break;end;end
 if numel(E)<card,cand=find(eligible&w>1e-10&~ismember((1:numel(w))',E));[~,o]=sort(cost(cand),'ascend');E=[E;cand(o(1:min(card-numel(E),numel(o))))];end
 E=unique(E,'stable');assert(numel(E)==card);pool(seed)=describe_block(sprintf('%s_%02d',prefix,seed),'CANDIDATE_POOL','BOUNDED_EXACT_DELIVERY',E,w,groups,cost,cfg,source,groupsFull,toFull,template);
end
end

function b=describe_block(name,phase,method,E,w,groups,cost,cfg,source,groupsFull,toFull,template)
b=block_template();b.name=name;b.phase=phase;b.method=method;b.death=reshape(E,[],1);raw=w;raw(E)=0;d=compute_delivery_metrics(embed(raw,toFull,template),source.map,groupsFull,cfg,source.machine);inc=compute_delivery_metrics(embed(w,toFull,template),source.map,groupsFull,cfg,source.machine);b.rawGain=inc.T_total-d.T_total;b.predictedRepairCost=sum(cost(E));b.deletedWeight=sum(w(E));b.affectedCP=numel(unique(arrayfun(@(g)g.cpIndex,groups(layer_ids(E,groups)))));b.affectedLayers=numel(layer_ids(E,groups));b.fullyRemovedLayers=count_fully_removed(E,w,groups);b.rawDeltaEnergy=d.T_energy-inc.T_energy;b.rawDeltaSpot=d.T_spot-inc.T_spot;b.rawDeltaIrradiation=d.T_irradiation-inc.T_irradiation;b.rawDeltaGantry=d.T_gantry-inc.T_gantry;b.rawDeltaBuffer=d.T_buffer-inc.T_buffer;b.currentScore=b.rawGain/max(b.predictedRepairCost,1e-12);
end

function [r,gRows,dRows,sRow]=analyze_block(id,b,w,wa,anchor,reference,model,D,patient,cfg,source,groups,groupsFull,toFull,template,spec,anchorGate,geom,cg,wall)
raw=w;raw(b.death)=0;rawPlan=evaluate_plan(raw,model,D,patient,cfg,source,groups,groupsFull,toFull,template);after=evaluate_plan(wa,model,D,patient,cfg,source,groups,groupsFull,toFull,template);[rawGate,~]=evaluate_clinical_gates(D,raw,spec,false);[afterGate,~]=evaluate_clinical_gates(D,wa,spec,false);st=clinical_state(after,reference);rawSpatial=spatial_proxy(raw,groups,geom,cfg);afterSpatial=spatial_proxy(wa,groups,geom,cfg);incSpatial=spatial_proxy(w,groups,geom,cfg);survive=true(size(w));survive(b.death)=false;redis=wa(survive)-w(survive);extraKilled=sum(w(survive)>cfg.spotThreshold&wa(survive)<=cfg.spotThreshold);
r=empty_response();r.block=id;r.name=b.name;r.phase=b.phase;r.method=b.method;r.cardinality=numel(b.death);r.deletedWeight=sum(w(b.death));r.affectedControlPoints=numel(unique(geom.cp(b.death)));r.affectedLayers=numel(unique(geom.layer(b.death)));r.fullyRemovedLayers=count_fully_removed(b.death,w,groups);r.objectiveIncumbent=anchor.objective;r.objectiveRaw=rawPlan.objective;r.objectiveAfter=after.objective;r.deltaFRaw=rawPlan.objective-anchor.objective;r.deltaFAfter=after.objective-anchor.objective;r.predictedBDTReduction=anchor.delivery.T_total-rawPlan.delivery.T_total;r.deltaTRealized=after.delivery.T_total-anchor.delivery.T_total;r.realizedBDTReduction=-r.deltaTRealized;r.predictedRealDelta=b.predictedRealDelta;r.maxRawGateDeterioration=max_gate_deterioration(rawGate,anchorGate,spec);r.maxAfterGateDeterioration=max_gate_deterioration(afterGate,anchorGate,spec);r.clinicallyFeasible=st.feasible;r.activeSpotsAfter=after.activeSpots;r.activeLayersAfter=after.activeLayers;r.energySwitchChangeRaw=rawPlan.delivery.nSwitchUp-anchor.delivery.nSwitchUp;r.energySwitchChangeAfter=after.delivery.nSwitchUp-anchor.delivery.nSwitchUp;r.switchMagnitudeChangeRaw=rawPlan.delivery.totalSwitchMagnitude-anchor.delivery.totalSwitchMagnitude;r.switchMagnitudeChangeAfter=after.delivery.totalSwitchMagnitude-anchor.delivery.totalSwitchMagnitude;r.spatialSpanChangeRaw=rawSpatial-incSpatial;r.spatialSpanChangeAfter=afterSpatial-incSpatial;r.survivorWeightChange=sum(redis);r.survivorL1Redistribution=sum(abs(redis));r.survivorsIncreased=sum(redis>1e-10);r.survivorsDecreased=sum(redis<-1e-10);r.extraSpotsKilledByRepair=extraKilled;r.extraLayersKilledByRepair=max(0,rawPlan.activeLayers-after.activeLayers);r.ipoptIterations=sum([cg.history.iterations]);r.primalInfeasibility=cg.lastSolver.primalInfeasibility;r.dualInfeasibility=cg.lastSolver.dualInfeasibility;r.solverStatus=cg.lastSolver.statusMessage;r.solverWallSeconds=sum([cg.history.solverWallSeconds]);r.totalWallSeconds=wall;
r.rawDeltaEnergy=rawPlan.delivery.T_energy-anchor.delivery.T_energy;r.repairDeltaEnergy=after.delivery.T_energy-rawPlan.delivery.T_energy;r.rawDeltaSpot=rawPlan.delivery.T_spot-anchor.delivery.T_spot;r.repairDeltaSpot=after.delivery.T_spot-rawPlan.delivery.T_spot;r.rawDeltaIrradiation=rawPlan.delivery.T_irradiation-anchor.delivery.T_irradiation;r.repairDeltaIrradiation=after.delivery.T_irradiation-rawPlan.delivery.T_irradiation;r.rawDeltaGantry=rawPlan.delivery.T_gantry-anchor.delivery.T_gantry;r.repairDeltaGantry=after.delivery.T_gantry-rawPlan.delivery.T_gantry;r.rawDeltaBuffer=rawPlan.delivery.T_buffer-anchor.delivery.T_buffer;r.repairDeltaBuffer=after.delivery.T_buffer-rawPlan.delivery.T_buffer;
gRows=repmat(empty_gate_row(),numel(spec)*2,1);q=0;for i=1:numel(spec),q=q+1;gRows(q)=make_gate(id,b,'RAW',spec(i),anchorGate(i),rawGate(i));q=q+1;gRows(q)=make_gate(id,b,'AFTER_REPAIR',spec(i),anchorGate(i),afterGate(i));end
names={'T_energy','T_spot','T_irradiation','T_gantry','T_buffer','T_total'};dRows=repmat(empty_component_row(),numel(names),1);for i=1:numel(names),nm=names{i};dRows(i)=struct('block',id,'name',b.name,'phase',b.phase,'component',nm,'incumbent',anchor.delivery.(nm),'raw',rawPlan.delivery.(nm),'afterRepair',after.delivery.(nm),'rawDelta',rawPlan.delivery.(nm)-anchor.delivery.(nm),'repairDelta',after.delivery.(nm)-rawPlan.delivery.(nm),'realizedDelta',after.delivery.(nm)-anchor.delivery.(nm));end
sRow=empty_support_row();sRow.block=id;sRow.name=b.name;sRow.phase=b.phase;sRow.proposedDeaths=numel(b.death);sRow.permanentProposedDeaths=sum(wa(b.death)<=1e-10);sRow.sameEventReturns=sum(wa(b.death)>1e-10);sRow.extraSurvivorDeaths=extraKilled;sRow.finalPositiveSpots=after.activeSpots;sRow.finalActiveLayers=after.activeLayers;
end

function cal=derive_mechanistic_calibration(rows,card)
use=[rows.cardinality]==card&ismember({rows.phase},{'LEGACY_CALIBRATION','NEW_CALIBRATION'});R=rows(use);assert(numel(R)>=3);deletedIrr=-[R.rawDeltaIrradiation];repairIrr=[R.repairDeltaIrradiation];rhoIrr=median(repairIrr./max(deletedIrr,1e-12));structGap=[R.repairDeltaEnergy]+[R.repairDeltaSpot]+[R.repairDeltaGantry]+[R.repairDeltaBuffer];rhoStruct=median(structGap./max(1,[R.fullyRemovedLayers]));cal=struct('cardinality',card,'nCalibrationBlocks',numel(R),'rhoIrradiation',rhoIrr,'secondsPerFullyRemovedLayerRepair',rhoStruct,'derivation','raw exact BDT plus calibrated irradiation redistribution and structural threshold correction');
end
function x=repair_aware_prediction(b,cal,machine),x=-b.rawGain+cal.rhoIrradiation*(b.deletedWeight/machine.irradiation.muRate)+cal.secondsPerFullyRemovedLayerRepair*b.fullyRemovedLayers;end

function s=summarize(rows,held,cal)
old=abs(-[held.predictedBDTReduction]-[held.deltaTRealized]);nw=abs([held.predictedRealDelta]-[held.deltaTRealized]);valid=isfinite(nw);oldMae=mean(old(valid));newMae=mean(nw(valid));ix=find(strcmp({held.method},'REPAIR_AWARE_DELIVERY'),1);if ~isempty(ix)&&held(ix).realizedBDTReduction>0&&newMae<oldMae,class='REPAIR_AWARE_PREDICTION_SUPPORTED';elseif newMae<oldMae,class='CALIBRATION_IMPROVED_BUT_DELIVERY_BENEFIT_NOT_CONFIRMED';else,class='REPAIR_AWARE_PREDICTION_NOT_SUPPORTED';end;s=struct('classification',class,'oldPredictionMAE',oldMae,'newPredictionMAE',newMae,'rhoIrradiation',cal.rhoIrradiation,'structuralCorrection',cal.secondsPerFullyRemovedLayerRepair,'heldoutBlocks',numel(held));
end

function b=block_template(),b=struct('name','','phase','','method','','death',[],'rawGain',0,'predictedRepairCost',0,'predictedRealDelta',NaN,'deletedWeight',0,'affectedCP',0,'affectedLayers',0,'fullyRemovedLayers',0,'rawDeltaEnergy',0,'rawDeltaSpot',0,'rawDeltaIrradiation',0,'rawDeltaGantry',0,'rawDeltaBuffer',0,'currentScore',0);end
function r=empty_response(),r=struct('block',0,'name','','phase','','method','','cardinality',0,'deletedWeight',0,'affectedControlPoints',0,'affectedLayers',0,'fullyRemovedLayers',0,'objectiveIncumbent',0,'objectiveRaw',0,'objectiveAfter',0,'deltaFRaw',0,'deltaFAfter',0,'predictedBDTReduction',0,'deltaTRealized',0,'realizedBDTReduction',0,'predictedRealDelta',NaN,'maxRawGateDeterioration',0,'maxAfterGateDeterioration',0,'clinicallyFeasible',false,'activeSpotsAfter',0,'activeLayersAfter',0,'energySwitchChangeRaw',0,'energySwitchChangeAfter',0,'switchMagnitudeChangeRaw',0,'switchMagnitudeChangeAfter',0,'spatialSpanChangeRaw',0,'spatialSpanChangeAfter',0,'survivorWeightChange',0,'survivorL1Redistribution',0,'survivorsIncreased',0,'survivorsDecreased',0,'extraSpotsKilledByRepair',0,'extraLayersKilledByRepair',0,'rawDeltaEnergy',0,'repairDeltaEnergy',0,'rawDeltaSpot',0,'repairDeltaSpot',0,'rawDeltaIrradiation',0,'repairDeltaIrradiation',0,'rawDeltaGantry',0,'repairDeltaGantry',0,'rawDeltaBuffer',0,'repairDeltaBuffer',0,'ipoptIterations',0,'primalInfeasibility',0,'dualInfeasibility',0,'solverStatus','','solverWallSeconds',0,'totalWallSeconds',0);end
function r=empty_gate_row(),r=struct('block',0,'name','','phase','','state','','structure','','metric','','sense','','incumbent',0,'value',0,'delta',0,'limit',0,'pass',false);end
function r=empty_component_row(),r=struct('block',0,'name','','phase','','component','','incumbent',0,'raw',0,'afterRepair',0,'rawDelta',0,'repairDelta',0,'realizedDelta',0);end
function r=empty_support_row(),r=struct('block',0,'name','','phase','','proposedDeaths',0,'permanentProposedDeaths',0,'sameEventReturns',0,'extraSurvivorDeaths',0,'finalPositiveSpots',0,'finalActiveLayers',0);end
function r=make_gate(id,b,state,sp,inc,v),if strcmp(sp.sense,'lower'),p=v>=sp.limit-1e-7;else,p=v<=sp.limit+1e-7;end;r=struct('block',id,'name',b.name,'phase',b.phase,'state',state,'structure',sp.structure,'metric',sp.metric,'sense',sp.sense,'incumbent',inc,'value',v,'delta',v-inc,'limit',sp.limit,'pass',p);end

function r=max_gate_deterioration(v,a,s),r=0;for i=1:numel(s),if strcmp(s(i).sense,'lower'),d=a(i)-v(i);else,d=v(i)-a(i);end;r=max(r,d);end,end
function ids=layer_ids(E,groups),hit=false(numel(groups),1);mask=false(max(cellfun(@max,{groups.ix})),1);mask(E)=true;for k=1:numel(groups),hit(k)=any(mask(groups(k).ix));end;ids=find(hit);end
function n=count_fully_removed(E,w,groups),mask=false(size(w));mask(E)=true;n=0;for k=1:numel(groups),ix=groups(k).ix;active=ix(w(ix)>1e-10);n=n+~isempty(active)&&all(mask(active));end,end
function o=oracle_order(pool),cost=[pool.predictedRepairCost];gain=[pool.rawGain];ok=cost<=median(cost);score=gain;score(~ok)=-Inf;[~,o]=sort(score,'descend');end
function E=cardinality_block(master,eligible,cost,n),E=master(eligible(master));E=unique(E,'stable');E=E(1:min(n,numel(E)));if numel(E)<n,c=find(eligible&~ismember((1:numel(eligible))',E));[~,o]=sort(cost(c),'ascend');E=[E;c(o(1:n-numel(E)))];end;assert(numel(E)==n);end
function c=spot_cost(w,g,J,spec,f),c=abs(g.*w)/max(1,abs(f));for q=1:numel(spec),if strcmp(spec(q).sense,'lower'),c=c+abs(J(q,:)'.*w);end,end;c=c+1e-12;end
function g=geometry_arrays(map,stf),n=numel(map);g=struct('cp',zeros(n,1),'layer',zeros(n,1),'x',zeros(n,1),'y',zeros(n,1));pairs=[[map.cpIndex]' [map.energyIndex]'];[~,~,g.layer]=unique(pairs,'rows','stable');for i=1:n,m=map(i);q=double(stf(m.beamNum).ray(m.rayNum).rayPos_bev);g.cp(i)=m.cpIndex;g.x(i)=q(1);g.y(i)=q(3);end,end
function v=spatial_proxy(w,groups,g,cfg),v=0;for k=1:numel(groups),ix=groups(k).ix;ix=ix(w(ix)>cfg.spotThreshold);if numel(ix)>1,v=v+(max(g.x(ix))-min(g.x(ix)))+(max(g.y(ix))-min(g.y(ix)));end,end,end
function T=pool_table(p),T=table((1:numel(p))',{p.name}',[p.rawGain]',[p.predictedRepairCost]',[p.predictedRealDelta]',[p.deletedWeight]',[p.affectedCP]',[p.affectedLayers]',[p.fullyRemovedLayers]','VariableNames',{'candidate','name','rawBDTGain','predictedRepairCost','predictedRealDelta','deletedWeight','affectedCP','affectedLayers','fullyRemovedLayers'});end
function checkpoint(o,k,b,w,cg,r,g,d,s),save(fullfile(o,sprintf('block_%02d.mat',k)),'b','w','cg','r','g','d','s','-v7.3');end
function flush(o,r,g,d,s),if ~isempty(r),writetable(struct2table(r,'AsArray',true),fullfile(o,'deletion_repair_response.csv'));end;if ~isempty(g),writetable(struct2table(g,'AsArray',true),fullfile(o,'clinical_gate_response.csv'));end;if ~isempty(d),writetable(struct2table(d,'AsArray',true),fullfile(o,'bdt_component_response.csv'));end;if ~isempty(s),writetable(struct2table(s,'AsArray',true),fullfile(o,'support_response.csv'));end,end
function write_report(o,x),f=fopen(fullfile(o,'REPAIR_RESPONSE_CALIBRATION_REPORT.md'),'w');c=onCleanup(@()fclose(f));fprintf(f,'# Repair-response calibration\n\nStatus: `%s`\n\nHeld-out raw-deletion prediction MAE: %.6g s.\n\nHeld-out repair-aware prediction MAE: %.6g s.\n\nCalibrated irradiation restoration ratio: %.6g.\n\nStructural repair correction: %.6g s per fully removed layer.\n',x.summary.classification,x.summary.oldPredictionMAE,x.summary.newPredictionMAE,x.calibration.rhoIrradiation,x.calibration.secondsPerFullyRemovedLayerRepair);end

function p=evaluate_plan(w,model,D,patient,cfg,source,groups,groupsFull,toFull,template),[f,~,d]=evaluate_matrad_dose_model(model,w,false);z=embed(w,toFull,template);p=struct('objective',f,'maxConstraintViolation',d.maxConstraintViolation,'dose',compute_dvh_metrics(full(D*w),patient.ct,patient.cst,cfg),'delivery',compute_delivery_metrics(z,source.map,groupsFull,cfg,source.machine),'activeSpots',nnz(w>1e-10),'activeLayers',count_layers(w,groups,1e-10));end
function s=clinical_state(p,r),[pass,worst,detail]=dose_quality(p.dose,r.dose);s=struct('feasible',pass&&p.maxConstraintViolation<=1e-6,'dosePass',pass,'constraintPass',p.maxConstraintViolation<=1e-6,'worstAdverse',worst,'detail',{detail});end
function [pass,worst,rows]=dose_quality(c,r),pass=true;worst=0;rows={};for i=1:numel(c.structures),a=r.structures(i);b=c.structures(i);if a.isTarget,keys={'D95','D98'};sense='lower';elseif strcmpi(a.type,'OAR')&&~ismember(upper(a.name),{'BODY','EXTERNAL'}),keys={'Dmean','Dmax'};sense='upper';else,continue;end;for k=1:numel(keys),m=keys{k};if strcmp(sense,'lower'),lim=.98*a.(m);ok=b.(m)>=lim;adv=max(0,100*(a.(m)-b.(m))/max(abs(a.(m)),eps));else,lim=a.(m)+max(.2,.02*max(abs(a.(m)),1));ok=b.(m)<=lim;adv=max(0,100*(b.(m)-a.(m))/max(abs(a.(m)),eps));end;rows(end+1,:)={a.name,m,b.(m),lim,ok};pass=pass&&ok;worst=max(worst,adv);end,end,end
function fullw=embed(w,toFull,template),fullw=zeros(size(template));fullw(toFull)=w;end
function n=count_layers(w,g,t),n=0;for i=1:numel(g),n=n+any(w(g(i).ix)>t);end,end
function D=nominal(d),D=d.physicalDose;if iscell(D),D=D{1};end,end
function add_paths(root,here),f={'config','planning','mapping','objective','delivery','reduction','evaluation','integrated','robustness'};for i=1:numel(f),addpath(fullfile(root,f{i}));end;addpath(fullfile(root,'experiments','repeated_dormant_replacement'));addpath(fullfile(root,'experiments','bdt_aware_active_gate'));addpath(here);end
function create_empty(d),if exist(d,'dir')==7,e=dir(d);e=e(~ismember({e.name},{'.','..'}));assert(isempty(e));else,mkdir(d);end,end
function m=merge_structs(a,b),m=a;f=fieldnames(b);for i=1:numel(f),k=f{i};if isfield(m,k)&&isstruct(m.(k))&&isstruct(b.(k)),m.(k)=merge_structs(m.(k),b.(k));else,m.(k)=b.(k);end,end,end
